// Remove the first and last character of the string
// Unescape \" to " and \\ to \
// Other escape sequences are NOT handled (e.g. \n remains \n)
func removeQuotesAndUnescape(s any) string {
	str := s.(string)
	if len(str) < 3 {
		return ""
	}

	newStr := ""
	backSlash := false
	for _, ch := range str[1 : len(str)-1] {
		if backSlash {
			if ch == '"' || ch == '\\' {
				newStr += string(ch)
			} else {
				newStr += "\\" + string(ch)
			}
			backSlash = false
		} else if ch == '\\' {
			backSlash = true
		} else {
			newStr += string(ch)
		}
	}

	return newStr
}

